    result={};used=set()
    for index,chapter in enumerate(data['chapters'],1):
        section=chapter.get('source_metadata',{}).get('section',index)
        for unit in chapter['verses']:
            anchor=unit['id'] if counts[unit['id']]==1 else f"section-{section}-{unit['id']}"
